USE datastudent;
SET NAMES utf8mb4;
START TRANSACTION;

-- Semua Kls RPL Harus Ada
INSERT IGNORE INTO classrooms (major_id, name, level, rombel, status, created_at, updated_at)
SELECT m.id, 'X-RPL-1', 'X', 1, 'Aktif', NOW(), NOW() FROM majors m WHERE m.code = 'RPL' LIMIT 1;
INSERT IGNORE INTO classrooms (major_id, name, level, rombel, status, created_at, updated_at)
SELECT m.id, 'XI-RPL-1', 'XI', 1, 'Aktif', NOW(), NOW() FROM majors m WHERE m.code = 'RPL' LIMIT 1;
INSERT IGNORE INTO classrooms (major_id, name, level, rombel, status, created_at, updated_at)
SELECT m.id, 'XII-RPL-1', 'XII', 1, 'Aktif', NOW(), NOW() FROM majors m WHERE m.code = 'RPL' LIMIT 1;

DROP TEMPORARY TABLE IF EXISTS tmp_rpl_full;
CREATE TEMPORARY TABLE tmp_rpl_full (

 nis varchar(30), nisn varchar(10), full_name varchar(255), birth_place varchar(255), birth_date date, nik varchar(30), gender_id bigint unsigned, religion_id bigint unsigned, phone varchar(25), email varchar(255), address text, postal_code varchar(10), level enum('X','XI','XII'), notes text,
 father_name varchar(255), father_job varchar(255), father_income varchar(255), father_phone varchar(25), mother_name varchar(255), mother_job varchar(255), mother_income varchar(255), mother_phone varchar(25), guardian_name varchar(255), guardian_job varchar(255), guardian_income varchar(255), guardian_phone varchar(25),
 school_name varchar(255), weight decimal(5,2), height decimal(5,2), disability text, extra_json longtext
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
