-- Students: update existing matching NISN, otherwise insert. Notes JSON preserves source-only fields.
INSERT INTO students (religion_id,gender_id,citizenship_id,nis,nisn,full_name,birth_place,birth_date,phone,email,address,postal_code,notes,created_at,updated_at)
SELECT t.religion_id, t.gender_id, COALESCE((SELECT id FROM citizenships WHERE code = 'WNI' LIMIT 1), 1), t.nis, t.nisn, t.full_name, t.birth_place, t.birth_date, t.phone, t.email, t.address, t.postal_code, t.extra_json, NOW(), NOW()
FROM tmp_rpl_full t
ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),birth_place=VALUES(birth_place),birth_date=VALUES(birth_date),phone=VALUES(phone),email=VALUES(email),address=VALUES(address),postal_code=VALUES(postal_code),notes=VALUES(notes),updated_at=NOW();

-- Family data. Occupation and income are mapped against master tables; unknown labels remain NULL.
INSERT INTO student_family (
    student_id,
    father_name, father_occupation_id, father_income_category_id, father_phone,
    mother_name, mother_occupation_id, mother_income_category_id, mother_phone,
    guardian_name, guardian_occupation_id, guardian_income_category_id, guardian_phone,
    relationship_type_id,
    created_at, updated_at
)
SELECT s.id,
       t.father_name,
       CASE 
           WHEN t.father_job IN ('Karyawan Swasta', 'Pegawai Swasta') THEN (SELECT id FROM occupations WHERE name = 'Pegawai Swasta' LIMIT 1)
           WHEN t.father_job = 'Buruh' THEN (SELECT id FROM occupations WHERE name = 'Lainnya' LIMIT 1)
           WHEN t.father_job IN ('Tidak bekerja', 'Tidak Bekerja') THEN (SELECT id FROM occupations WHERE name = 'Tidak Bekerja' LIMIT 1)
           WHEN t.father_job LIKE '%PNS%' THEN (SELECT id FROM occupations WHERE name = 'PNS' LIMIT 1)
           WHEN t.father_job LIKE '%TNI%' OR t.father_job LIKE '%POLRI%' THEN (SELECT id FROM occupations WHERE name = 'TNI/POLRI' LIMIT 1)
           WHEN t.father_job LIKE '%Pedagang%' OR t.father_job = 'Perdagangan' OR t.father_job = 'Wiraswasta' THEN (SELECT id FROM occupations WHERE name = 'Wiraswasta' LIMIT 1)
           WHEN t.father_job = 'Petani' THEN (SELECT id FROM occupations WHERE name = 'Petani' LIMIT 1)
           WHEN t.father_job = 'Nelayan' THEN (SELECT id FROM occupations WHERE name = 'Nelayan' LIMIT 1)
           WHEN t.father_job = 'Guru' THEN (SELECT id FROM occupations WHERE name = 'Guru' LIMIT 1)
           WHEN t.father_job = 'Dokter' THEN (SELECT id FROM occupations WHERE name = 'Dokter' LIMIT 1)
           WHEN t.father_job IS NOT NULL AND TRIM(t.father_job) != '' THEN (SELECT id FROM occupations WHERE name = 'Lainnya' LIMIT 1)
           ELSE NULL
       END,
       CASE 
           WHEN t.father_income IS NULL OR t.father_income IN ('Tidak Berpenghasilan', '< Rp1.000.000', 'Kurang dari Rp 1.000.000') THEN (SELECT id FROM income_categories WHERE name = 'Kurang dari 1 juta' LIMIT 1)
           WHEN t.father_income LIKE '%1.000.000%1.999.999%' OR t.father_income LIKE '%1.000.001%2.000.000%' THEN (SELECT id FROM income_categories WHERE name = '1 - 2 juta' LIMIT 1)
           WHEN t.father_income LIKE '%1.000.001%3.000.000%' OR t.father_income LIKE '%2.000.001%3.000.000%' THEN (SELECT id FROM income_categories WHERE name = '2 - 3 juta' LIMIT 1)
           WHEN t.father_income LIKE '%3.000.001%5.000.000%' THEN (SELECT id FROM income_categories WHERE name = '3 - 5 juta' LIMIT 1)
           WHEN t.father_income LIKE '%5.000.001%10.000.000%' THEN (SELECT id FROM income_categories WHERE name = '5 - 10 juta' LIMIT 1)
           WHEN t.father_income LIKE '%10.000.001%' OR t.father_income LIKE '>%' OR t.father_income LIKE '%Lebih dari%' THEN (SELECT id FROM income_categories WHERE name = 'Lebih dari 10 juta' LIMIT 1)
           ELSE (SELECT id FROM income_categories WHERE name = 'Kurang dari 1 juta' LIMIT 1)
       END,
       t.father_phone,

       t.mother_name,
       CASE 
           WHEN t.mother_job IN ('Karyawan Swasta', 'Pegawai Swasta') THEN (SELECT id FROM occupations WHERE name = 'Pegawai Swasta' LIMIT 1)
           WHEN t.mother_job = 'Buruh' THEN (SELECT id FROM occupations WHERE name = 'Lainnya' LIMIT 1)
           WHEN t.mother_job IN ('Tidak bekerja', 'Tidak Bekerja') THEN (SELECT id FROM occupations WHERE name = 'Tidak Bekerja' LIMIT 1)
           WHEN t.mother_job LIKE '%PNS%' THEN (SELECT id FROM occupations WHERE name = 'PNS' LIMIT 1)
           WHEN t.mother_job LIKE '%TNI%' OR t.mother_job LIKE '%POLRI%' THEN (SELECT id FROM occupations WHERE name = 'TNI/POLRI' LIMIT 1)
           WHEN t.mother_job LIKE '%Pedagang%' OR t.mother_job = 'Perdagangan' OR t.mother_job = 'Wiraswasta' THEN (SELECT id FROM occupations WHERE name = 'Wiraswasta' LIMIT 1)
           WHEN t.mother_job = 'Petani' THEN (SELECT id FROM occupations WHERE name = 'Petani' LIMIT 1)
           WHEN t.mother_job = 'Nelayan' THEN (SELECT id FROM occupations WHERE name = 'Nelayan' LIMIT 1)
           WHEN t.mother_job = 'Guru' THEN (SELECT id FROM occupations WHERE name = 'Guru' LIMIT 1)
           WHEN t.mother_job = 'Dokter' THEN (SELECT id FROM occupations WHERE name = 'Dokter' LIMIT 1)
           WHEN t.mother_job IS NOT NULL AND TRIM(t.mother_job) != '' THEN (SELECT id FROM occupations WHERE name = 'Lainnya' LIMIT 1)
           ELSE NULL
       END,
       CASE 
           WHEN t.mother_income IS NULL OR t.mother_income IN ('Tidak Berpenghasilan', '< Rp1.000.000', 'Kurang dari Rp 1.000.000') THEN (SELECT id FROM income_categories WHERE name = 'Kurang dari 1 juta' LIMIT 1)
           WHEN t.mother_income LIKE '%1.000.000%1.999.999%' OR t.mother_income LIKE '%1.000.001%2.000.000%' THEN (SELECT id FROM income_categories WHERE name = '1 - 2 juta' LIMIT 1)
           WHEN t.mother_income LIKE '%1.000.001%3.000.000%' OR t.mother_income LIKE '%2.000.001%3.000.000%' THEN (SELECT id FROM income_categories WHERE name = '2 - 3 juta' LIMIT 1)
           WHEN t.mother_income LIKE '%3.000.001%5.000.000%' THEN (SELECT id FROM income_categories WHERE name = '3 - 5 juta' LIMIT 1)
           WHEN t.mother_income LIKE '%5.000.001%10.000.000%' THEN (SELECT id FROM income_categories WHERE name = '5 - 10 juta' LIMIT 1)
           WHEN t.mother_income LIKE '%10.000.001%' OR t.mother_income LIKE '>%' OR t.mother_income LIKE '%Lebih dari%' THEN (SELECT id FROM income_categories WHERE name = 'Lebih dari 10 juta' LIMIT 1)
           ELSE (SELECT id FROM income_categories WHERE name = 'Kurang dari 1 juta' LIMIT 1)
       END,
       t.mother_phone,

       CASE WHEN t.guardian_name IS NOT NULL AND TRIM(t.guardian_name) != '' THEN t.guardian_name ELSE NULL END,
       CASE 
           WHEN t.guardian_name IS NULL OR TRIM(t.guardian_name) = '' THEN NULL
           WHEN t.guardian_job IN ('Karyawan Swasta', 'Pegawai Swasta') THEN (SELECT id FROM occupations WHERE name = 'Pegawai Swasta' LIMIT 1)
           WHEN t.guardian_job = 'Buruh' THEN (SELECT id FROM occupations WHERE name = 'Lainnya' LIMIT 1)
           WHEN t.guardian_job IN ('Tidak bekerja', 'Tidak Bekerja') THEN (SELECT id FROM occupations WHERE name = 'Tidak Bekerja' LIMIT 1)
           WHEN t.guardian_job LIKE '%PNS%' THEN (SELECT id FROM occupations WHERE name = 'PNS' LIMIT 1)
           WHEN t.guardian_job LIKE '%TNI%' OR t.guardian_job LIKE '%POLRI%' THEN (SELECT id FROM occupations WHERE name = 'TNI/POLRI' LIMIT 1)
           WHEN t.guardian_job LIKE '%Pedagang%' OR t.guardian_job = 'Perdagangan' OR t.guardian_job = 'Wiraswasta' THEN (SELECT id FROM occupations WHERE name = 'Wiraswasta' LIMIT 1)
           WHEN t.guardian_job = 'Petani' THEN (SELECT id FROM occupations WHERE name = 'Petani' LIMIT 1)
           WHEN t.guardian_job = 'Nelayan' THEN (SELECT id FROM occupations WHERE name = 'Nelayan' LIMIT 1)
           WHEN t.guardian_job = 'Guru' THEN (SELECT id FROM occupations WHERE name = 'Guru' LIMIT 1)
           WHEN t.guardian_job = 'Dokter' THEN (SELECT id FROM occupations WHERE name = 'Dokter' LIMIT 1)
           WHEN t.guardian_job IS NOT NULL AND TRIM(t.guardian_job) != '' THEN (SELECT id FROM occupations WHERE name = 'Lainnya' LIMIT 1)
           ELSE NULL
       END,
       CASE 
           WHEN t.guardian_name IS NULL OR TRIM(t.guardian_name) = '' THEN NULL
           WHEN t.guardian_income IS NULL OR t.guardian_income IN ('Tidak Berpenghasilan', '< Rp1.000.000', 'Kurang dari Rp 1.000.000') THEN (SELECT id FROM income_categories WHERE name = 'Kurang dari 1 juta' LIMIT 1)
           WHEN t.guardian_income LIKE '%1.000.000%1.999.999%' OR t.guardian_income LIKE '%1.000.001%2.000.000%' THEN (SELECT id FROM income_categories WHERE name = '1 - 2 juta' LIMIT 1)
           WHEN t.guardian_income LIKE '%1.000.001%3.000.000%' OR t.guardian_income LIKE '%2.000.001%3.000.000%' THEN (SELECT id FROM income_categories WHERE name = '2 - 3 juta' LIMIT 1)
           WHEN t.guardian_income LIKE '%3.000.001%5.000.000%' THEN (SELECT id FROM income_categories WHERE name = '3 - 5 juta' LIMIT 1)
           WHEN t.guardian_income LIKE '%5.000.001%10.000.000%' THEN (SELECT id FROM income_categories WHERE name = '5 - 10 juta' LIMIT 1)
           WHEN t.guardian_income LIKE '%10.000.001%' OR t.guardian_income LIKE '>%' OR t.guardian_income LIKE '%Lebih dari%' THEN (SELECT id FROM income_categories WHERE name = 'Lebih dari 10 juta' LIMIT 1)
           ELSE NULL
       END,
       CASE WHEN t.guardian_name IS NOT NULL AND TRIM(t.guardian_name) != '' THEN t.guardian_phone ELSE NULL END,

       NULL,
       NOW(),
       NOW()
FROM tmp_rpl_full t
JOIN students s ON s.nisn = t.nisn
ON DUPLICATE KEY UPDATE 
    father_name = VALUES(father_name),
    father_occupation_id = VALUES(father_occupation_id),
    father_income_category_id = VALUES(father_income_category_id),
    father_phone = VALUES(father_phone),
    mother_name = VALUES(mother_name),
    mother_occupation_id = VALUES(mother_occupation_id),
    mother_income_category_id = VALUES(mother_income_category_id),
    mother_phone = VALUES(mother_phone),
    guardian_name = VALUES(guardian_name),
    guardian_occupation_id = VALUES(guardian_occupation_id),
    guardian_income_category_id = VALUES(guardian_income_category_id),
    guardian_phone = VALUES(guardian_phone),
    relationship_type_id = VALUES(relationship_type_id),
    updated_at = NOW();

-- Education history: Sekolah Asal -> SMP history (education level SMP).
INSERT INTO student_education_history (student_id, education_level_id, school_name, entry_year, graduation_year, is_graduated, notes, created_at, updated_at)
SELECT s.id, COALESCE((SELECT id FROM education_levels WHERE name = 'SMP' LIMIT 1), 2), t.school_name, NULL, NULL, 1, NULL, NOW(), NOW()
FROM tmp_rpl_full t
JOIN students s ON s.nisn = t.nisn
WHERE t.school_name IS NOT NULL AND TRIM(t.school_name) != ''
ON DUPLICATE KEY UPDATE school_name = VALUES(school_name), updated_at = NOW();

-- Health: height/weight and kebutuhan khusus.
INSERT INTO student_healths (student_id, height, weight, disabilities, notes, created_at, updated_at)
SELECT s.id, t.height, t.weight, t.disability, JSON_UNQUOTE(JSON_EXTRACT(t.extra_json, '$.lingkar_kepala')), NOW(), NOW()
FROM tmp_rpl_full t
JOIN students s ON s.nisn = t.nisn
ON DUPLICATE KEY UPDATE height = VALUES(height), weight = VALUES(weight), disabilities = VALUES(disabilities), notes = VALUES(notes), updated_at = NOW();

-- Enrollment 2026/2027, active.
INSERT INTO student_enrollments (student_id, academic_year_id, classroom_id, student_status_id, enrolled_at, created_at, updated_at)
SELECT s.id,
       COALESCE((SELECT id FROM academic_years WHERE name = '2026/2027' LIMIT 1), (SELECT id FROM academic_years WHERE is_active = 1 LIMIT 1), 1),
       c.id,
       COALESCE((SELECT id FROM student_statuses WHERE name = 'Aktif' LIMIT 1), 1),
       '2026-07-01',
       NOW(),
       NOW()
FROM tmp_rpl_full t
JOIN students s ON s.nisn = t.nisn
JOIN classrooms c ON c.major_id = (SELECT id FROM majors WHERE code = 'RPL' LIMIT 1) AND c.level = t.level AND c.rombel = 1
ON DUPLICATE KEY UPDATE classroom_id = VALUES(classroom_id), student_status_id = VALUES(student_status_id), ended_at = NULL, updated_at = NOW();

-- Verification
SELECT c.name AS kelas, COUNT(se.student_id) AS jumlah
FROM classrooms c
LEFT JOIN student_enrollments se ON se.classroom_id = c.id
WHERE c.major_id = (SELECT id FROM majors WHERE code = 'RPL' LIMIT 1)
GROUP BY c.id, c.name, c.level
ORDER BY c.level;

SELECT COUNT(*) AS total_rpl_imported FROM tmp_rpl_full;

COMMIT;
